app.get('/api/deliveries/:deliveryId/live-tracking', authenticate, async (req, res) => {
  const delivery = await DeliveryOrder.findOne({
    where: { id: req.params.deliveryId, customerId: req.user.id }
  });
  if (!delivery && req.user.role !== 'courier') {
    return res.status(403).json({ error: 'Unauthorized to stream tracking for this delivery' });
  }
  res.writeHead(200, {
    'Content-Type': 'text/event-stream',
    'Cache-Control': 'no-cache',
    Connection: 'keep-alive'
  });

  const onLocationUpdate = (coords) => {
    res.write(`data: ${JSON.stringify(coords)}\n\n`);
  };

  trackingEmitter.on(`delivery:${req.params.deliveryId}`, onLocationUpdate);
  req.on('close', () => {
    trackingEmitter.off(`delivery:${req.params.deliveryId}`, onLocationUpdate);
  });
});
